/* Original by Andor Saga
   2019.06.15: converted to p5.js v0.8.0
*/
let myShader,
		mouse = [0, 0, 0];
let pimg;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	myShader = createShader(vert, frag);
	shader(myShader);
  noStroke();
	pimg = loadImage('https://openprocessing.org/sketch/729414/files/logo.jpg');

  let c = document.getElementById('defaultCanvas0');
  c.addEventListener('contextmenu', e => { e.preventDefault(); });
}

function mousePressed(event) {
  mouse[event.which - 1] = 1;
}

function mouseReleased(event) {
  mouse[event.which - 1] = 0;
}

function draw() {
  translate(-width/2, -height/2);

	shader(myShader);
	myShader.setUniform('time', millis());
	myShader.setUniform('res', [width, height]);
	myShader.setUniform('aspect', width/height);
	myShader.setUniform('mouse', [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), height - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), mouse[0], mouse[2]]);
	myShader.setUniform('texture0', pimg);

	rect(0, 0, width, height, 1, 1);
}

// === Tab: tab2 ===
let frag = `
#ifdef GL_ES
  precision highp float;
  precision mediump int;
#endif

	varying vec3 var_vertPos;
	varying vec4 var_vertCol;
	varying vec3 var_vertNormal;
	varying vec2 var_vertTexCoord;

  // 
  uniform sampler2D texture0;
	uniform vec2 res;
	uniform vec4 mouse;
	uniform float time;
  uniform float aspect;

	void main() {
    vec2 pos = gl_FragCoord.xy / res; 

    // invert y for texture
    pos.y = 1.0 - pos.y;

		if(aspect <= 1.){
			pos.x *= aspect;
			pos.x += (1. - aspect) * .5;
		}else{
			pos.y *= 1./aspect;
			pos.y += (1. - 1./aspect) * .5;
		}

    vec4 col = vec4(1., pos.x * (cos(time/1000.) + 1.)/2., pos.y*(sin(time/1000.) + 1.)/2., 1.);

		if(mouse.z == 1.){ col.r = .5;}
		if(mouse.w == 1.){ col.g = .5;}

    float i = (mouse.x/res.x) * 10.0;
    float amp = (1.-mouse.y/res.y) * 0.06;
		pos.y += sin(time/1000.0 + (gl_FragCoord.x*i/100.0) ) * amp;

		vec4 texel = texture2D(texture0, pos);

		gl_FragColor = texel * col;

    // if still waiting for image....
    if(texel.xy == vec2(0.)){
      gl_FragColor = vec4(pos.x, pos.y, 1., 1.);
    }

    if(mouse.x < gl_FragCoord.x + 1. && mouse.x > gl_FragCoord.x - 1.){
      //gl_FragColor = vec4(0.);
    }
    if(mouse.y < gl_FragCoord.y + 1. && mouse.y > gl_FragCoord.y - 1.){
      //gl_FragColor = vec4(0.);
    }
}`;

// === Tab: tab3 ===
let vert = `
#ifdef GL_ES
	precision highp float;
	precision mediump int;
#endif

attribute vec3 aPosition;
attribute vec4 aVertexColor;
attribute vec3 aNormal;
attribute vec2 aTexCoord;

varying vec3 var_vertPos;
varying vec4 var_vertCol;
varying vec3 var_vertNormal;
varying vec2 var_vertTexCoord;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;

void main() {
	gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0 );
	var_vertPos = aPosition;
	var_vertCol = aVertexColor;
	var_vertNormal = aNormal;
	var_vertTexCoord = aTexCoord;
}
`;

